-- token_hub schema for the performance test, derived from the token_hub DDL provided by the application team.
-- Changes vs. the original DDL (only these):
--   * every statement has ON CLUSTER '{cluster}' so it is created on both replicas;
--   * t_billing_records_mv: the two columns `client_ip` and `forwarded_for` are removed from the MV column list and
--     SELECT. They do not exist in the target table t_billing_records; older ClickHouse versions silently dropped them,
--     ClickHouse 26.8 rejects the original DDL with "Code: 8 THERE_IS_NO_COLUMN: SELECT query outputs column with name
--     'client_ip', which is not found in the target table". Removing them stores exactly the same data as before;
--   * t_billing_events_kafka_source uses ENGINE = Null (same columns) instead of ENGINE = Kafka, because the
--     production Kafka brokers (alikafka ... aliyuncs.com) are not reachable from AWS. An INSERT into a Null table
--     fires the materialized view exactly like a Kafka consumer block does, so the MV pipeline can be load-tested.
-- t_billing_records and t_billing_records_mv are otherwise verbatim.

CREATE DATABASE IF NOT EXISTS token_hub ON CLUSTER '{cluster}';

CREATE TABLE token_hub.t_billing_events_kafka_source ON CLUSTER '{cluster}' (`event_type` String, `event_source` String, `timestamp` UInt64, `data` String) ENGINE = Null;

CREATE TABLE token_hub.t_billing_records ON CLUSTER '{cluster}' (`kafka_meta_event_type` String, `kafka_meta_event_source` String, `kafka_meta_timestamp` DateTime64(3) COMMENT '事件时间（毫秒精度，转换自 UInt64）', `id` UInt64, `user_id` UInt64, `org_id` UInt64 DEFAULT 0 COMMENT '组织ID（0=个人模式；与MySQL t_billing_records.org_id一致）', `model_code` String, `api_key_id` UInt64, `provider_id` UInt64, `trace_id` String, `user_header_req_id` String, `provider_req_header_req_id` String, `provider_res_body_id` String, `provider_res_header_req_id` String, `status` String, `error_code` String, `error_message` String, `supplier_error` String, `scene` String, `is_fallback` UInt8, `input_tokens` UInt32, `input_text_tokens` UInt32 DEFAULT 0 COMMENT '文本输入Token数（模态拆分，参与计费）', `input_image_tokens` UInt32 DEFAULT 0 COMMENT '图像输入Token数（模态拆分，参与计费）', `input_cache_tokens` UInt32, `cache_type` String DEFAULT '' COMMENT '缓存类型：ephemeral=显式缓存，空=隐式缓存/未返回', `cache_creation_input_tokens` UInt32, `cache_creation_1h_input_tokens` UInt32, `cache_creation_5m_input_tokens` UInt32, `audio_input_tokens` UInt32, `output_tokens` UInt32, `audio_output_tokens` UInt32, `cost` UInt64, `discount_rate` Decimal(5, 4), `is_stream` UInt8, `session_id` String DEFAULT '' COMMENT '会话ID（从请求 metadata.user_id 提取）', `request_at` DateTime64(3) DEFAULT toDateTime64(0, 3) COMMENT '请求进入时间（relay 请求进入系统时的时间点，来自 data.request_at）', `t_first_event` Int32 DEFAULT 0 COMMENT '首帧耗时(ms，用户维度：首个上游 SSE data 帧)', `t_first_content` Int32 DEFAULT 0 COMMENT '首内容耗时(ms，用户维度：首个含内容 delta，经典 TTFT)', `total` Int32 DEFAULT 0 COMMENT '总耗时(ms，用户维度)', `thinking_enabled` UInt8 DEFAULT 0 COMMENT '是否开启 thinking（Anthropic extended thinking）: 0=否, 1=是', `currency` LowCardinality(String) DEFAULT '' COMMENT 'cost的记账单位: nUSD/nCNY; 空=历史数据,按全局base_price_unit解读', `billing_mode` UInt8 DEFAULT 0 COMMENT '计费口径: 0=按token计费 1=按次计费(tokens恒为0,费用来自per_call_price)', `ext_info` String DEFAULT '' COMMENT '扩展信息JSON，按秒计费示例：{"billing_seconds":5.2}；非按秒计费为空', `created_at` DateTime64(3) COMMENT '计费时间（来自data.created_at）', INDEX idx_user_id user_id TYPE minmax GRANULARITY 4) ENGINE = ReplicatedMergeTree('/clickhouse/tables/token_hub/t_billing_records/{shard}', '{replica}') PARTITION BY toYYYYMM(created_at) ORDER BY (kafka_meta_event_type, created_at, user_id) SETTINGS index_granularity = 8192;

CREATE MATERIALIZED VIEW token_hub.t_billing_records_mv ON CLUSTER '{cluster}' TO token_hub.t_billing_records (`kafka_meta_event_type` String, `kafka_meta_event_source` String, `kafka_meta_timestamp` DateTime64(3), `id` UInt64, `user_id` UInt64, `org_id` UInt64, `model_code` String, `api_key_id` UInt64, `provider_id` UInt64, `trace_id` String, `user_header_req_id` String, `provider_req_header_req_id` String, `provider_res_body_id` String, `provider_res_header_req_id` String, `status` String, `error_code` String, `error_message` String, `supplier_error` String, `scene` String, `is_fallback` UInt64, `input_tokens` UInt64, `input_text_tokens` UInt64, `input_image_tokens` UInt64, `input_cache_tokens` UInt64, `cache_type` String, `cache_creation_input_tokens` UInt64, `cache_creation_1h_input_tokens` UInt64, `cache_creation_5m_input_tokens` UInt64, `audio_input_tokens` UInt64, `output_tokens` UInt64, `audio_output_tokens` UInt64, `cost` UInt64, `discount_rate` Decimal(9, 4), `is_stream` UInt64, `session_id` String, `request_at` DateTime64(3), `t_first_event` Int64, `t_first_content` Int64, `total` Int64, `thinking_enabled` UInt64, `currency` String, `billing_mode` UInt64, `ext_info` String, `created_at` DateTime64(3)) AS SELECT event_type AS kafka_meta_event_type, event_source AS kafka_meta_event_source, toDateTime64(timestamp / 1000, 3) AS kafka_meta_timestamp, JSONExtractUInt(data, 'id') AS id, JSONExtractUInt(data, 'user_id') AS user_id, JSONExtractUInt(data, 'org_id') AS org_id, JSONExtractString(data, 'model_code') AS model_code, JSONExtractUInt(data, 'api_key_id') AS api_key_id, JSONExtractUInt(data, 'provider_id') AS provider_id, JSONExtractString(data, 'trace_id') AS trace_id, JSONExtractString(data, 'user_header_req_id') AS user_header_req_id, JSONExtractString(data, 'provider_req_header_req_id') AS provider_req_header_req_id, JSONExtractString(data, 'provider_res_body_id') AS provider_res_body_id, JSONExtractString(data, 'provider_res_header_req_id') AS provider_res_header_req_id, JSONExtractString(data, 'status') AS status, JSONExtractString(data, 'error_code') AS error_code, JSONExtractString(data, 'error_message') AS error_message, JSONExtractString(data, 'supplier_error') AS supplier_error, JSONExtractString(data, 'scene') AS scene, JSONExtractUInt(data, 'is_fallback') AS is_fallback, JSONExtractUInt(data, 'input_tokens') AS input_tokens, JSONExtractUInt(data, 'input_text_tokens') AS input_text_tokens, JSONExtractUInt(data, 'input_image_tokens') AS input_image_tokens, JSONExtractUInt(data, 'input_cache_tokens') AS input_cache_tokens, JSONExtractString(data, 'cache_type') AS cache_type, JSONExtractUInt(data, 'cache_creation_input_tokens') AS cache_creation_input_tokens, JSONExtractUInt(data, 'cache_creation_1h_input_tokens') AS cache_creation_1h_input_tokens, JSONExtractUInt(data, 'cache_creation_5m_input_tokens') AS cache_creation_5m_input_tokens, JSONExtractUInt(data, 'audio_input_tokens') AS audio_input_tokens, JSONExtractUInt(data, 'output_tokens') AS output_tokens, JSONExtractUInt(data, 'audio_output_tokens') AS audio_output_tokens, JSONExtractUInt(data, 'cost') AS cost, toDecimal32(JSONExtractFloat(data, 'discount_rate'), 4) AS discount_rate, JSONExtractUInt(data, 'is_stream') AS is_stream, JSONExtractString(data, 'session_id') AS session_id, toDateTime64(JSONExtractUInt(data, 'request_at') / 1000, 3) AS request_at, JSONExtractInt(data, 't_first_event') AS t_first_event, JSONExtractInt(data, 't_first_content') AS t_first_content, JSONExtractInt(data, 'total') AS total, JSONExtractUInt(data, 'thinking_enabled') AS thinking_enabled, JSONExtractString(data, 'currency') AS currency, JSONExtractUInt(data, 'billing_mode') AS billing_mode, JSONExtractString(data, 'ext_info') AS ext_info, toDateTime64(JSONExtractUInt(data, 'created_at') / 1000, 3) AS created_at FROM token_hub.t_billing_events_kafka_source;
